import {
  Component,
  h,
  Prop,
  Element,
  Watch,
  ComponentInterface,
  State,
  Method,
  Host,
  Event,
  EventEmitter,
} from '@stencil/core';
import classnames from 'classnames';
import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';
import {
  BeforeUploadHook,
  UploadChangeParam,
  UploadFile,
  UploadMaxCountConfig,
  UploadMaxCountBehavior,
  UpLoadSize,
} from './types';
import { file2Obj, updateFileList, removeFileItem, IUploadOption } from './utils';
import { isNumber } from 'lodash-es';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';

const prefix = 'upload';

/**
 * @slot default - Custom trigger content rendered inside the upload area.
 */
@Component({
  tag: 'ks-upload',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsUpload implements ComponentInterface {
  private uploadEl?: HTMLKsRcUploadElement;
  @Element() el!: HTMLKsUploadElement;

  /** The status of the upload component. */
  @Prop() status?: 'default' | 'error';
  /** The size of the upload file list, Can be one of the following values: `"sm"` or `"md"`. */
  @Prop() size: UpLoadSize = 'md';
  /** The accepted file types for upload, similar to the HTML `accept` attribute. */
  @Prop() accept?: string;
  /** The URL where the files will be uploaded. */
  @Prop() action?: string;
  /** Additional data sent with the upload request. */
  @Prop() data?: object;
  /** The name attribute value for the files in the upload request, sent to the backend. */
  @Prop() name = 'file';
  /** Disables the upload component, preventing file selection or drag-and-drop functionality. */
  @Prop() @FormContextValueReconcile() disabled = false;
  /** Whether multiple files can be uploaded at once. */
  @Prop() multiple = false;
  /** The headers to be sent along with the upload request. */
  @Prop() headers?: object;
  /** The HTTP method used for the upload request. */
  @Prop() method = 'post';
  /** The current list of files in the upload queue. */
  @Prop() @FormContextValueReconcile({ contextKey: 'valueFromContext' }) fileList?: UploadFile[];
  /** The default file list when the component is first rendered. */
  @Prop() defaultFileList: UploadFile[] = [];
  /** Whether or not to display the uploaded files list. */
  @Prop() showUploadList = true;
  /** A function to be called before the upload process begins, can be used to validate files. */
  @Prop() beforeUpload?: BeforeUploadHook;
  /** Description related to the upload, such as the types of uploads allowed. */
  @Prop() description = '';
  /** The maximum count of the fileList. */
  @Prop() maxCount?: UploadMaxCountConfig;

  /** A function to be called before a file is removed from the upload queue. */
  @Prop() beforeRemove?: (file: UploadFile & { detail: UploadFile }) => boolean | Promise<boolean>;
  /** Allows custom control of the upload process, overriding the default request behavior. */
  @Prop() customRequest?: (option: IUploadOption) => void;

  // @Prop() ondrop: (event: CustomEvent) => void;

  @Slot({ slotname: '_default' }) private children?: Slots<unknown>;

  /** Custom event emitted when the file list or upload state changes. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<UploadChangeParam<UploadFile>>;
  /** Custom event emitted when the file upload state errors. */
  @Event({ bubbles: false, composed: false }) ksError!: EventEmitter<UploadChangeParam<UploadFile>>;

  @Uncontrollable('fileList', 'defaultFileList', null) @State() private mergedFileList: UploadFile[] = [];

  @State() highlight = false;

  @State() isError = false;

  // TODO should implement this with `maxCount` correctly
  // @State() isExceededMax = false;

  @State() errorMessage = '';

  private ensureFileListUid(fileList?: UploadFile[]) {
    const timestamp = Date.now();
    (fileList || []).forEach((file, index) => {
      if (!file.uid && !Object.isFrozen(file)) {
        file.uid = `__AUTO__${timestamp}_${index}__`;
      }
    });
  }

  private getMaxCountConfig() {
    let value: number | undefined;
    let behavior: UploadMaxCountBehavior | undefined;

    if (isNumber(this.maxCount)) {
      value = this.maxCount;
    } else if (this.maxCount && typeof this.maxCount === 'object') {
      if (isNumber(this.maxCount.value)) {
        value = this.maxCount.value;
      }
      behavior = this.maxCount.behavior;
    }

    if (!this.multiple && !isNumber(value)) {
      value = 1;
    }

    if (!behavior) {
      behavior = 'reject';
    }

    return { value, behavior };
  }

  private applyMaxCount(fileList: UploadFile[]) {
    const { value, behavior } = this.getMaxCountConfig();
    if (!isNumber(value)) {
      return fileList;
    }
    if (behavior === 'replace') {
      return value === 1 ? fileList.slice(-1) : fileList.slice(-value);
    }
    return fileList.slice(0, value);
  }

  @Watch('fileList')
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  handleUpdateFileList(fileList) {
    this.ensureFileListUid(fileList);
    if (Array.isArray(fileList) && fileList.length === 0) {
      this.uploadEl?.clearInputValue();
    }
  }

  @Watch('disabled')
  handleUpdate() {
    this.children?.forEach((item) => {
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      item.disabled = this.disabled;
    });
  }

  private onInternalChange = (file: UploadFile, changedFileList: UploadFile[], event?: { percent: number }) => {
    const nextFileList = this.applyMaxCount([...changedFileList]);
    this.mergedFileList = nextFileList;
    const changeInfo: UploadChangeParam<UploadFile> = {
      file: file as UploadFile,
      fileList: nextFileList,
    };

    if (event) {
      changeInfo.event = event;
    }
    if (nextFileList.length === 0) {
      this.uploadEl?.clearInputValue();
    }

    const compositedChangeInfo = [...nextFileList];
    Object.assign(compositedChangeInfo, changeInfo);
    this.ksChange?.emit(changeInfo);
  };

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private onSuccess = ({ detail: { response, file, xhr } }) => {
    this.isError = false;
    const targetItem = file2Obj(file);

    targetItem.status = 'done';
    targetItem.percent = 100;
    targetItem.response = response;
    targetItem.xhr = xhr;

    const nextFileList = updateFileList(targetItem, this.mergedFileList);

    this.onInternalChange(targetItem, nextFileList);
  };

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private onProgress = ({ detail: { event, file } }) => {
    this.isError = false;
    const targetItem = file2Obj(file);
    targetItem.status = 'uploading';
    targetItem.percent = event.percent;

    const nextFileList = updateFileList(targetItem, this.mergedFileList);

    this.onInternalChange(targetItem, nextFileList);
  };

  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  private onFail = (e) => {
    const {
      detail: { event, file, error, response },
    } = e;

    if (error) {
      // this.ksChange?.emit({ file, fileList: [], error });
      this.ksError.emit({ file, fileList: [], error });
      this.isError = true;
      if (error === 'upload_exceeded_max_limit') {
        return;
      }
    }
    const targetItem = file2Obj(file);
    targetItem.status = 'error';
    targetItem.percent = event?.percent || 0;
    targetItem.response = response || error.message;
    const nextFileList = updateFileList(targetItem, this.mergedFileList);
    this.onInternalChange(targetItem, nextFileList, error);
  };

  /** @private DO NOT USE OR IT MAY CAUSE UNEXPECTED CONSEQUENCES. */
  @Method()
  async handleRemove(file: UploadFile) {
    let currentFile: UploadFile;
    await Promise.resolve(
      typeof this.beforeRemove === 'function' ? this.beforeRemove({ ...file, detail: file }) : this.beforeRemove,
    ).then((_) => {
      const removedFileList = removeFileItem(file, this.mergedFileList);

      if (removedFileList) {
        currentFile = { ...file, status: 'removed' };
        this.mergedFileList?.forEach((item) => {
          const matchKey = currentFile.uid !== undefined ? 'uid' : 'name';
          if (item[matchKey] === currentFile[matchKey] && !Object.isFrozen(item)) {
            item.status = 'removed';
          }
        });

        this.uploadEl?.abort(currentFile);

        this.onInternalChange(currentFile, removedFileList);
      }
    });
  }

  componentWillLoad() {
    this.children?.forEach((item) => {
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      item.disabled = this.disabled;
    });
  }

  componentDidLoad() {
    this.ensureFileListUid(this.mergedFileList);
    if (this.fileList === undefined) {
      this.mergedFileList = this.applyMaxCount(this.mergedFileList);
    }
  }

  render() {
    const displayFileList = this.applyMaxCount(this.mergedFileList);
    return (
      <Host class="KsUpload">
        <span
          class={classnames(prefix, {
            [`${prefix}--active`]: displayFileList.some((item) => item.status === 'uploading'),
          })}
        >
          <ks-rc-upload
            data={this.data}
            multiple={this.multiple}
            accept={this.accept}
            headers={this.headers}
            action={this.action}
            beforeUpload={this.beforeUpload}
            onsuccess={this.onSuccess}
            onfail={this.onFail}
            onpro={this.onProgress}
            name={this.name}
            disabled={this.disabled}
            ref={(el) => (this.uploadEl = el)}
            customRequest={this.customRequest}
            maxCount={this.getMaxCountConfig()}
            fileListLength={displayFileList.length}
          >
            <slot></slot>
          </ks-rc-upload>
          {this.description && (
            <ks-text variant="labelSm">
              <span class={{ disabled: this.disabled }}>{this.description}</span>
            </ks-text>
          )}
          {this.showUploadList && Boolean(displayFileList?.length) && (
            <ks-upload-list
              size={this.size}
              class={`${prefix}__file-list`}
              items={displayFileList}
              onremove={(file) => this.handleRemove(file)}
              disabled={this.disabled}
            ></ks-upload-list>
          )}
        </span>
      </Host>
    );
  }
}
